INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine maßgeschneiderte Lösung immer teurer als Standardsoftware ist?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Anforderungen"}, {"text": "Ja", "correct": false, "because": "Nicht immer teurer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, um eine spezifische Lösung zu entwickeln?', 3, '[{"text": "Kundenanforderungen", "correct": true, "because": "Basis der Entwicklung"}, {"text": "Schnelle Fertigstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind für eine maßgeschneiderte Anwendung wichtig?', 5, '[{"text": "Anforderungsanalyse", "correct": true, "because": "Definiert Bedarf"}, {"text": "Entwicklung", "correct": true, "because": "Erstellt Lösung"}, {"text": "Testen", "correct": true, "because": "Sichert Qualität"}, {"text": "Marketing", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sie passt sich genau an Prozesse an. b) Sie ist immer schneller entwickelt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist oft aufwendiger"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine spezielle Lösung plane?', 4, '[{"text": "Kundenwünsche", "correct": false, "because": "Grundlage der Entwicklung"}, {"text": "Technische Machbarkeit", "correct": false, "because": "Entscheidend"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass maßgeschneiderte Lösungen immer komplexer sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann einfach sein"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Projekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Anforderungen zu erheben?', 3, '[{"text": "Interviews", "correct": true, "because": "Direkte Kundeninfo"}, {"text": "Zufallsauswahl", "correct": false, "because": "Ineffizient"}, {"text": "Marketingkampagne", "correct": false, "because": "Anderer Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine spezifische Anwendung?', 5, '[{"text": "Exakte Anpassung", "correct": true, "because": "Passt zu Prozessen"}, {"text": "Effizienz", "correct": true, "because": "Optimiert Abläufe"}, {"text": "Einmaligkeit", "correct": true, "because": "Kundenspezifisch"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) sie flexibel ist und b) sie immer günstiger ist. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten oft höher"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine maßgeschneiderte Lösung zu entwickeln?', 4, '[{"text": "Anforderungen", "correct": false, "because": "Grundlage"}, {"text": "Programmierkenntnisse", "correct": false, "because": "Notwendig"}, {"text": "Designvorlagen", "correct": true, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine maßgeschneiderte Lösung immer wartungsintensiv?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Design"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine spezifische Anwendung effektiv?', 4, '[{"text": "Kundenspezifität", "correct": true, "because": "Passt genau"}, {"text": "Testphase", "correct": true, "because": "Sichert Qualität"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass sie nur für große Firmen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für KMUs"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer maßgeschneiderten Lösung?', 3, '[{"text": "Prozessoptimierung", "correct": true, "because": "Passt zu Abläufen"}, {"text": "Kostensenkung", "correct": false, "because": "Nicht immer"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Oft länger"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sie erfordert Anforderungsanalyse. b) Sie ist immer Standardsoftware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Gegenteil"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Testphase?', 4, '[{"text": "Qualitätssicherung", "correct": true, "because": "Findet Fehler"}, {"text": "Schnellere Lieferung", "correct": false, "because": "Verzögert oft"}, {"text": "Designverbesserung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine maßgeschneiderte Lösung Standardlösungen nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "Spezifisch entwickelt"}, {"text": "Ja", "correct": false, "because": "Individuell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine spezifische Anwendung?', 5, '[{"text": "Hohe Kosten", "correct": true, "because": "Entwicklung aufwendig"}, {"text": "Zeitaufwand", "correct": true, "because": "Längere Entwicklung"}, {"text": "Wartungsintensität", "correct": true, "because": "Spezifische Pflege"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Nicht Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist sie immer plattformabhängig?', 3, '[{"text": "Nein", "correct": true, "because": "Kann flexibel sein"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Design"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einer maßgeschneiderten Lösung?', 4, '[{"text": "Spezifischer Geschäftsprozess", "correct": true, "because": "Passt genau"}, {"text": "Standard-Bürosoftware", "correct": false, "because": "Standardlösung"}, {"text": "Schnelle Installation", "correct": false, "because": "Oft länger"}]');
